140	// Type builds one key press per character of s, reproducing a user typing
141	// into a text input. Use this instead of Key(s) when the target is a
142	// textinput: it consumes characters one keypress at a time. A space is built
143	// like Key("space").
144	func Type(s string) []tea.Msg {
145		msgs := make([]tea.Msg, 0, len(s))
146		for _, r := range s {
147			if r == ' ' {
148				msgs = append(msgs, spaceKey())
149				continue
150			}
151			msgs = append(msgs, tea.KeyPressMsg{Code: r, Text: string(r)})
152		}
153		return msgs
154	}
