161	// Msgs executes cmd and returns every message it produced, flattening the
162	// tea.Batch and tea.Sequence trees. A nil command, or one returning nil, yields
163	// no messages.
164	//
165	// The command runs synchronously on the calling goroutine. Do not pass a command
166	// that sleeps or performs I/O — tea.Tick blocks for its whole duration, and the
167	// Docker runners shell out. Assert on the command's identity or on model state
168	// instead for those.
169	func Msgs(cmd tea.Cmd) []tea.Msg {
170		if cmd == nil {
171			return nil
172		}
173		msg := cmd()
174		if msg == nil {
175			return nil
176		}
177		if batch, ok := msg.(tea.BatchMsg); ok {
178			var out []tea.Msg
179			for _, c := range batch {
180				out = append(out, Msgs(c)...)
181			}
182			return out
183		}
184		if seq, ok := sequenced(msg); ok {
185			var out []tea.Msg
186			for _, c := range seq {
187				out = append(out, Msgs(c)...)
188			}
189			return out
190		}
191		return []tea.Msg{msg}
192	}
193	
194	// sequenced reports whether msg is what tea.Sequence returns, and unpacks the
195	// commands it holds.
196	//
197	// tea.Batch answers with the exported tea.BatchMsg, but the equivalent for
198	// tea.Sequence is unexported — the runtime is its only intended reader, and it
199	// runs the commands one after another rather than concurrently. Its underlying
200	// type is []tea.Cmd, so reflection recovers them without depending on the name.
201	// Order is preserved, which is the whole point of a sequence: a view that emits
202	// "scan starting" before the scan itself relies on the first message arriving
203	// first.
204	func sequenced(msg tea.Msg) ([]tea.Cmd, bool) {
205		value := reflect.ValueOf(msg)
206		if value.Kind() != reflect.Slice || value.Type().Elem() != reflect.TypeFor[tea.Cmd]() {
207			return nil, false
208		}
209		// The element type was just checked, so every assertion below holds; a nil
210		// entry comes back as a nil tea.Cmd, which Msgs already ignores.
211		cmds := make([]tea.Cmd, 0, value.Len())
212		for i := range value.Len() {
213			cmds = append(cmds, value.Index(i).Interface().(tea.Cmd))
214		}
215		return cmds, true
216	}
217	
218	// Msg executes cmd and returns the single message it produced, or nil.
219	// It is the common case of Msgs for commands that emit exactly one message.
220	func Msg(cmd tea.Cmd) tea.Msg {
221		msgs := Msgs(cmd)
222		if len(msgs) == 0 {
223			return nil
224		}
225		return msgs[0]
226	}
