356	// ── Rule 110: the detection is race free ─────────────────────────────────────
357	
358	// The Cmds run on their own goroutines while Update and View run on the loop's.
359	// Under `mise run test-race` a Cmd that reads router state would be reported.
360	func TestThemeAutoDetectionIsRaceFree(t *testing.T) {
361		a := autoRouter(t, autoConfig("auto", "", ""))
362		testutil.FastTimers(t, &themeDetectTimeout)
363		testutil.FastTimers(t, &components.FooterMsgDuration)
364		cmd := a.themeInitCmd()
365	
366		var wg sync.WaitGroup
367		var msgs []tea.Msg
368		wg.Add(1)
369		go func() {
370			defer wg.Done()
371			msgs = testutil.Msgs(cmd)
372		}()
373		for range 50 {
374			_ = a.View()
375		}
376		a.Update(tea.BackgroundColorMsg{Color: color.White})
377		wg.Wait()
378	
379		if timeout, ok := firstOf[themeDetectTimeoutMsg](msgs); ok {
380			a.Update(timeout) // arrives after the answer: must change nothing
381		}
382		if theme.CurrentThemeName != "github-light" {
383			t.Errorf("CurrentThemeName = %q, want github-light", theme.CurrentThemeName)
384		}
385	}
386	
387	func firstOf[T tea.Msg](msgs []tea.Msg) (T, bool) {
388		for _, m := range msgs {
389			if v, ok := m.(T); ok {
390				return v, true
391			}
392		}
393		var zero T
394		return zero, false
395	}
