14	// DEVDESK-342: `mise run ci` replays the CI workflow locally. It must chain,
15	// sequentially and in order, the `mise run <task>` steps of ci.yml plus the
16	// local-only steps below (D149), so the two cannot drift apart: ci.yml is the
17	// steps of `mise run ci` minus localOnlySteps. mise.toml is read without a
18	// TOML library (none is in go.mod): the guard only needs the task headers,
19	// the description and the `run = [{ task = "..." }, ...]` array of [tasks.ci].
20	//
21	// DEVDESK-502 (D149 in docs/backlog.md): the CI no longer runs the tests, so
22	// ci.yml is `mise run ci` minus an explicit local-only set. The relation is
23	// checked in both directions: a step missing from ci.yml fails, and so does a
24	// local-only task that comes back into ci.yml, so tests return to the CI only
25	// by a decision that edits this file.
26	
27	var ciSteps = []string{"fmt-check", "vet", "lint", "build", "test", "test-race"}
28	
29	// localOnlySteps are the steps of `mise run ci` that ci.yml must NOT run.
30	// D149: the `Test` job of ci.yml only writes a summary line (the main-protection
31	// ruleset requires a check named `Test`), and the tests run on the maintainer's
32	// machine through `mise run ci`.
33	var localOnlySteps = []string{"test", "test-race"}
34	
35	// workflowSteps returns steps without the local-only ones, order preserved.
36	func workflowSteps(steps []string) []string {
37		var out []string
38		for _, s := range steps {
39			if !slices.Contains(localOnlySteps, s) {
40				out = append(out, s)
41			}
42		}
43		return out
44	}
