46	var (
47		taskHeaderRe = regexp.MustCompile(`(?m)^\[tasks\.([A-Za-z0-9_.-]+)\]\s*$`)
48		sectionRe    = regexp.MustCompile(`(?m)^\[`)
49		stepRe       = regexp.MustCompile(`task\s*=\s*"([^"]+)"`)
50	)
51	
52	// miseSection returns the body of [tasks.<name>] and the set of all task names.
53	func miseSection(t *testing.T, name string) (body string, all map[string]bool) {
54		t.Helper()
55		raw, err := os.ReadFile(filepath.Join(moduleRoot(t), "mise.toml"))
56		if err != nil {
57			t.Fatal(err)
58		}
59		src := string(raw)
60		all = map[string]bool{}
61		for _, m := range taskHeaderRe.FindAllStringSubmatch(src, -1) {
62			all[m[1]] = true
63		}
64		loc := regexp.MustCompile(`(?m)^\[tasks\.` + regexp.QuoteMeta(name) + `\]\s*$`).FindStringIndex(src)
65		if loc == nil {
66			return "", all
67		}
68		rest := src[loc[1]:]
69		if next := sectionRe.FindStringIndex(rest); next != nil {
70			rest = rest[:next[0]]
71		}
72		return rest, all
73	}
74	
75	func ciTaskBody(t *testing.T) (string, map[string]bool) {
76		t.Helper()
77		body, all := miseSection(t, "ci")
78		if body == "" {
79			t.Fatal("mise.toml has no [tasks.ci] section (DEVDESK-342)")
80		}
81		return body, all
82	}
