84	func ciRunSteps(t *testing.T, body string) []string {
85		t.Helper()
86		var steps []string
87		for _, m := range stepRe.FindAllStringSubmatch(body, -1) {
88			steps = append(steps, m[1])
89		}
90		return steps
91	}
